function runStages(stages) {
  const passed = [];
  for (let i = 0; i < stages.length; i++) {
    const code = stages[i].run();
    if (code !== 0) {
      return { passed, failed: stages[i].name, skipped: stages.slice(i + 1).map((s) => s.name) };
    }
    passed.push(stages[i].name);
  }
  return { passed, failed: null, skipped: [] };
}

