function auditGate(vulnerabilities, exceptions, today) {
  return Object.entries(vulnerabilities)
    .filter(([, v]) => v.severity === "high" || v.severity === "critical")
    .filter(([name]) => !exceptions.some((e) => e.packageName === name && e.expires >= today))
    .map(([name]) => name)
    .sort();
}

