function breaksPreviousRelease(sql, columnsUsedByPrevious) {
  const text = sql.toLowerCase().replaceAll('"', "");
  const used = columnsUsedByPrevious.map((c) => c.toLowerCase());
  const touched = text.match(/(?:rename|drop) column (\w+)/);
  if (touched && used.includes(touched[1])) return true;
  return /add column \w+ .*not null/.test(text) && !text.includes("default");
}

