function rollbackTarget(history, current, liveSchema) {
  const index = history.findIndex((release) => release.tag === current);
  for (let i = index - 1; i >= 0; i--) {
    const release = history[i];
    if (release.healthy && release.worksWithSchemaUpTo >= liveSchema) return release.tag;
  }
  return "fix forward";
}

